import { EventEmitter } from "node:events";
import { createConnection } from "node:net";
import WebSocket from "ws";
import { checkChannel } from "./broker-channel.mjs";
import { sendFetch } from "./index.mjs";
import { zdrRequest } from "./retention.mjs";
import OpenAI from "openai";
import { ResponsesWS } from "openai/resources/responses/ws";

const refusedBeforeSend = Symbol("broker WebSocket refusal");
const maxManagedFrameBytes = 16 * 1024 * 1024;

function storedContinuationUnavailable() {
  return Response.json(
    { error: "ai_continuation_unavailable" },
    { status: 409 },
  );
}

function responseCreateFrame(body) {
  const request = { ...body };
  delete request.stream;
  delete request.background;
  return { type: "response.create", ...request };
}

/**
 * Review keeps each observed call/output and screenshot, without replaying them
 * as computer protocol. Responses refuses computer outputs beside multiple
 * ordinary images. The retained conversation and execution sends stay intact.
 */
function reviewComputerInput(input) {
  if (
    !input.some((item) => item.type === "computer_call_output") ||
    input
      .flatMap((item) => (Array.isArray(item.content) ? item.content : []))
      .filter((part) => part.type === "input_image").length < 2
  )
    return input;
  return input.map((item) => {
    if (item.type === "computer_call")
      return {
        role: "assistant",
        content: [{ type: "output_text", text: JSON.stringify(item) }],
      };
    if (item.type !== "computer_call_output") return item;
    const original = structuredClone(item);
    const image = {};
    for (const key of ["image_url", "file_id"])
      if (typeof original.output?.[key] === "string") {
        image[key] = original.output[key];
        delete original.output[key];
      }
    return {
      role: "user",
      content: [
        { type: "input_text", text: JSON.stringify(original) },
        ...(Object.keys(image).length
          ? [{ type: "input_image", ...image, detail: "original" }]
          : []),
      ],
    };
  });
}

function reviewWire(request) {
  if (request.tool_choice !== "none") return request;
  const input = reviewComputerInput(request.input);
  if (input === request.input) return request;
  return {
    ...request,
    input,
    // No action is permitted in recap. An unused computer definition still
    // refuses multiple images even after its historical outputs are quoted.
    ...(request.tool_choice === "none"
      ? { tools: request.tools.filter((tool) => tool.type !== "computer") }
      : {}),
  };
}

// The broker's private close codes certify that the current message was never
// forwarded. A lost TCP connection does not carry that assurance.
async function managedResponsesSocket({ socketPath, headers }) {
  await checkChannel(socketPath);
  const socket = new WebSocket("ws://localhost/ai-bound/v1/responses", {
    headers,
    createConnection: () => createConnection(socketPath),
    handshakeTimeout: 10000,
    maxPayload: maxManagedFrameBytes,
    perMessageDeflate: false,
  });
  const transport = Object.assign(new EventEmitter(), {
    socket,
    close: () => socket.terminate(),
    send: (frame) => socket.send(frame),
  });
  socket.on("message", (data) => {
    let event;
    const wire = data.toString("utf8");
    try {
      event = JSON.parse(wire);
    } catch {
      return socket.terminate();
    }
    if (!event || typeof event.type !== "string") return socket.terminate();
    transport.emit("event", event, wire);
  });
  socket.on("error", (error) => transport.emit("error", error));
  socket.on("close", (code) => {
    if (code === 4001 || code === 4002) transport.emit("brokerRefusal", code);
    transport.emit("close");
  });
  return transport;
}

/** Create one bound session from the connection already authorized by the broker. */
export function createManagedResponsesSession({
  connection,
  storeResponses,
  omitContent,
  requestAI,
  recordWebSocketFrame,
}) {
  if (!connection.socketPath || !connection.headers["x-kaijan-ai-connection"])
    return undefined;
  const omit = () =>
    typeof omitContent === "function" ? omitContent() : omitContent === true;
  return createResponsesSession({
    storeResponses,
    recordWebSocketFrame,
    requestAI:
      requestAI ??
      ((body, signal) =>
        sendFetch(connection, {
          method: "POST",
          headers: {
            "content-type": "application/json",
            ...(omit() ? { "x-kaijan-ai-content": "omit" } : {}),
          },
          body: JSON.stringify(body),
          signal,
        })),
    managedWebSocket: {
      socketPath: connection.socketPath,
      headers: connection.headers,
      omitContent: omit,
    },
  });
}

/**
 * One Responses conversation. The owner serializes sends and closes it
 * after reporting. Other injected HTTP senders keep their existing route.
 */
export function createResponsesSession({
  apiKey,
  requestAI,
  managedWebSocket,
  storeResponses = false,
  record,
  recordWebSocketFrame,
}) {
  if (managedWebSocket && !requestAI)
    throw new Error("Managed WebSocket requires the same broker HTTP sender");
  const history = new Map();
  const storedWebSocketIds = new Set();
  const receivedWebSocketFrames = new WeakMap();
  const client = requestAI
    ? null
    : new OpenAI({
        apiKey,
        baseURL: "https://api.openai.com/v1",
        maxRetries: 0,
      });
  let socket,
    socketModel,
    cachedId,
    httpOnly = Boolean(requestAI && !managedWebSocket),
    closed = false;
  // Recording observes an event; its edits must not change transport or history.
  const recordEvent = (event) => record?.(structuredClone(event));
  const http =
    requestAI ??
    ((body, signal) =>
      fetch("https://api.openai.com/v1/responses", {
        method: "POST",
        redirect: "error",
        headers: {
          Authorization: `Bearer ${apiKey}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(body),
        signal,
      }));

  function closeSocket() {
    socket?.close();
    socket = undefined;
    socketModel = undefined;
    cachedId = undefined;
  }
  function replay(body) {
    const turns = [];
    let id = body.previous_response_id;
    while (id) {
      const prior = history.get(id);
      if (!prior) throw new Error("Runner continuation history unavailable");
      turns.push(prior);
      id = prior.previous;
    }
    const request = { ...body };
    delete request.previous_response_id;
    // The physical wire is caller-owned; callbacks may normalize it. Keep the
    // retained task, output and encrypted reasoning isolated from those edits.
    const input = structuredClone([
      ...turns.reverse().flatMap((turn) => [...turn.input, ...turn.output]),
      ...body.input,
    ]);
    // OpenAI validates replayed computer outputs against the current tools too.
    // A tool-free recap keeps tool selection disabled after restoring the schema.
    const needsComputer =
      input.some((item) => item.type === "computer_call_output") &&
      !request.tools?.some((tool) => tool.type === "computer");
    return {
      ...request,
      input,
      ...(needsComputer
        ? {
            tools: [...(request.tools ?? []), { type: "computer" }],
            ...(!request.tools?.length ? { tool_choice: "none" } : {}),
          }
        : {}),
    };
  }
  function retain(body, response) {
    if (typeof response?.id === "string" && Array.isArray(response.output))
      history.set(response.id, {
        previous: body.previous_response_id,
        input: structuredClone(body.input),
        output: structuredClone(response.output),
      });
  }
  async function connect(signal, model) {
    // Core binds a managed socket to its first model. Runner recap can use a
    // different model, with the original grant and stored continuation.
    if (
      socket?.socket.readyState === 1 &&
      (!managedWebSocket || model === socketModel)
    )
      return;
    closeSocket();
    const current = managedWebSocket
      ? await managedResponsesSocket(managedWebSocket)
      : new ResponsesWS(client, { reconnect: null });
    socket = current;
    socketModel = model;
    // The SDK emits a protocol error again after its raw event. The active
    // waiter handles transport errors; keep idle/error-event cleanup observed.
    current.on("error", () => {});
    await new Promise((resolve, reject) => {
      const cleanup = () => {
        current.socket.off("open", opened);
        current.off("error", failed);
        current.off("close", failed);
        signal?.removeEventListener("abort", aborted);
      };
      const opened = () => {
        cleanup();
        resolve();
      };
      const failed = () => {
        cleanup();
        reject(new Error("Runner WebSocket connection unavailable"));
      };
      const aborted = () => {
        cleanup();
        closeSocket();
        reject(signal.reason);
      };
      current.socket.on("open", opened);
      current.on("error", failed);
      current.on("close", failed);
      signal?.addEventListener("abort", aborted, { once: true });
      if (signal?.aborted) aborted();
      else if (current.socket.readyState === 1) opened();
    });
  }
  async function websocket(frame, signal, inactivityTimeoutMs) {
    const current = socket;
    return new Promise((resolve, reject) => {
      const cleanup = () => {
        clearTimeout(inactivity);
        current.off("event", event);
        current.off("brokerRefusal", brokerRefusal);
        current.off("error", failed);
        current.off("close", failed);
        signal?.removeEventListener("abort", aborted);
      };
      const event = (value, wire) => {
        inactivity?.refresh();
        if (
          ![
            "response.completed",
            "response.failed",
            "response.incomplete",
            "error",
          ].includes(value.type)
        )
          return;
        if (recordWebSocketFrame && typeof wire === "string")
          receivedWebSocketFrames.set(value, wire);
        cleanup();
        resolve(value);
      };
      const failed = () => {
        cleanup();
        closeSocket();
        reject(
          new Error(
            "Runner WebSocket response interrupted; inference outcome unknown",
          ),
        );
      };
      const aborted = () => {
        cleanup();
        closeSocket();
        reject(signal.reason);
      };
      const brokerRefusal = (code) => {
        cleanup();
        resolve({ [refusedBeforeSend]: code });
      };
      const inactivity =
        inactivityTimeoutMs === undefined
          ? undefined
          : setTimeout(() => {
              cleanup();
              closeSocket();
              reject(
                new DOMException(
                  "Provider socket inactivity timeout",
                  "TimeoutError",
                ),
              );
            }, inactivityTimeoutMs);
      current.on("brokerRefusal", brokerRefusal);
      current.on("event", event);
      current.on("error", failed);
      current.on("close", failed);
      signal?.addEventListener("abort", aborted, { once: true });
      if (signal?.aborted) {
        aborted();
        return;
      }
      try {
        current.send(frame);
      } catch (error) {
        cleanup();
        closeSocket();
        reject(error);
      }
    });
  }
  async function sendHttp(original, signal, review) {
    // Explorer's Agents session owns full history and original HTTP dispatch.
    if (managedWebSocket) {
      signal?.throwIfAborted();
      return http(original, signal);
    }
    const wire = storeResponses
      ? original
      : review
        ? reviewWire(replay(original))
        : replay(original);
    await recordEvent({ transport: "http", phase: "request", body: wire });
    signal?.throwIfAborted();
    const response = await http(wire, signal);
    // Read a clone so the owner retains the original status/headers/body.
    let body;
    try {
      body = await response.clone().json();
    } catch {
      /* Owner handles malformed bodies. */
    }
    await recordEvent({
      transport: "http",
      phase: "response",
      status: response.status,
      body,
    });
    if (response.ok && !storeResponses) retain(original, body);
    return response;
  }
  return {
    async send(request, signal, { review = false, inactivityTimeoutMs } = {}) {
      if (closed) throw new Error("Runner Responses session is closed");
      signal?.throwIfAborted();
      const original = storeResponses
        ? structuredClone({ ...request, store: true })
        : managedWebSocket
          ? zdrRequest(request)
          : structuredClone({
              ...zdrRequest(request),
              include: [
                ...new Set([
                  ...(request.include ?? []),
                  "reasoning.encrypted_content",
                ]),
              ],
            });
      const storedWebSocketContinuation = storedWebSocketIds.has(
        original.previous_response_id,
      );
      if (httpOnly && !storedWebSocketContinuation)
        return sendHttp(original, signal, review);
      const managedFrame = managedWebSocket
        ? JSON.stringify({
            ...responseCreateFrame(original),
            ...(managedWebSocket.omitContent?.()
              ? { kaijan_content: "omit" }
              : {}),
          })
        : undefined;
      if (
        managedFrame &&
        Buffer.byteLength(managedFrame) > maxManagedFrameBytes
      )
        return sendHttp(original, signal, review);
      try {
        await connect(signal, original.model);
      } catch {
        signal?.throwIfAborted();
        closeSocket();
        if (!storedWebSocketContinuation) httpOnly = true;
        await recordEvent({
          transport: "websocket",
          phase: "unavailable-before-dispatch",
        });
        return storedWebSocketContinuation
          ? storedContinuationUnavailable()
          : sendHttp(original, signal, review);
      }
      let wire =
        storeResponses ||
        managedWebSocket ||
        (!review &&
          original.previous_response_id &&
          original.previous_response_id === cachedId)
          ? original
          : replay(original);
      if (review && !managedWebSocket && !storeResponses)
        wire = reviewWire(wire);
      const sendFrame = async () => {
        await recordEvent({
          transport: "websocket",
          phase: "request",
          body: wire,
        });
        signal?.throwIfAborted();
        if (recordWebSocketFrame && managedFrame !== undefined)
          await recordWebSocketFrame("request", managedFrame);
        return websocket(
          managedFrame ?? responseCreateFrame(wire),
          signal,
          inactivityTimeoutMs,
        );
      };
      let event = await sendFrame();
      if (event[refusedBeforeSend] === 4001 && storedWebSocketContinuation) {
        // The broker confirmed this turn did not reach the gateway. Its prior
        // response ID belongs to the WebSocket route even after reconnecting.
        closeSocket();
        try {
          await connect(signal, original.model);
        } catch {
          signal?.throwIfAborted();
          closeSocket();
          return storedContinuationUnavailable();
        }
        event = await sendFrame();
      }
      if (event[refusedBeforeSend] !== undefined) {
        closeSocket();
        if (event[refusedBeforeSend] === 4001)
          return storedWebSocketContinuation
            ? storedContinuationUnavailable()
            : sendHttp(original, signal, review);
        return Response.json(
          { error: "ai_connection_changed" },
          { status: 412 },
        );
      }
      const receivedFrame = receivedWebSocketFrames.get(event);
      if (receivedFrame !== undefined)
        await recordWebSocketFrame("response", receivedFrame);
      await recordEvent({
        transport: "websocket",
        phase: "response",
        body: event,
      });
      if (event.type === "error") {
        cachedId = undefined;
        if (
          !storeResponses &&
          !managedWebSocket &&
          event.error?.code === "previous_response_not_found"
        )
          return sendHttp(original, signal, review);
        const status =
          event.status ??
          event.error?.status ??
          (event.error?.type === "rate_limit_error"
            ? 429
            : event.error?.type === "server_error"
              ? 500
              : 400);
        const providerHttpStatus = event.provider_http_status;
        const providerFailureCode = event.provider_failure_code;
        const headers = new Headers();
        if (managedWebSocket) {
          if (
            Number.isInteger(providerHttpStatus) &&
            providerHttpStatus >= 400 &&
            providerHttpStatus <= 599
          )
            headers.set(
              "x-kaijan-provider-http-status",
              String(providerHttpStatus),
            );
          if (
            providerHttpStatus === 429 &&
            providerFailureCode === "provider_quota_exhausted"
          )
            headers.set("x-kaijan-provider-failure-code", providerFailureCode);
        }
        const quotaRefusal =
          managedWebSocket &&
          status === 429 &&
          providerHttpStatus === 429 &&
          providerFailureCode === "provider_quota_exhausted";
        return Response.json(
          {
            error: event.error,
            ...(quotaRefusal
              ? {
                  statusCode: 429,
                  code: "ai_gateway_rejected",
                  retryable: false,
                }
              : {}),
          },
          { status, headers },
        );
      }
      if (
        managedWebSocket &&
        storeResponses &&
        event.type === "response.completed" &&
        event.response?.store !== false &&
        typeof event.response?.id === "string"
      ) {
        storedWebSocketIds.add(event.response.id);
      }
      if (!managedWebSocket && !storeResponses) {
        cachedId = event.response.id;
        retain(original, event.response);
      }
      return Response.json(event.response);
    },
    close() {
      closed = true;
      closeSocket();
      history.clear();
      storedWebSocketIds.clear();
    },
  };
}
